// spec: specs/date-now.md
// seed: tests/seed.reg1.geo.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/reg1.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.07, longitude: 34.79, accuracy: 10 },
  permissions: ['geolocation'],
});

test.describe('דייט עכשיו — включение, выключение, тариф', () => {
  test('Бесплатный тариф: «שעתיים»/«3 שעות» под замком → предложение Premium, режим не включается @iphone @prod-safe (#1fd43a)', async ({ page }) => {
    const setDateNowRequests: string[] = [];
    page.on('request', (req) => {
      if (req.url().includes('/rpc/set_date_now')) setDateNowRequests.push(req.url());
    });

    // 1. Открыть /map, нажать «דייט עכשיו» (после заставки MAGNET)
    await page.goto('/map');
    const pill = page.getByTestId('date-now-pill');
    await expect(pill).toBeVisible({ timeout: 30_000 });
    await pill.click();

    await expect(page.getByText('פנוי/ה לדייט עכשיו?')).toBeVisible();
    await expect(page.getByRole('button', { name: '30 דק׳' })).toBeVisible();
    await expect(page.getByRole('button', { name: /^שעה/ })).toBeVisible();
    await expect(page.getByRole('button', { name: /^שעתיים/ })).toBeVisible();
    await expect(page.getByRole('button', { name: /^3 שעות/ })).toBeVisible();

    // 2. Нажать чип «שעתיים»
    await page.getByRole('button', { name: /^שעתיים/ }).click();

    const upsell = page.getByRole('dialog');
    await expect(upsell.getByRole('button', { name: 'לשדרג ל-Premium' })).toBeVisible();
    await expect(upsell.getByRole('button', { name: 'לא עכשיו' })).toBeVisible();
    expect(setDateNowRequests).toHaveLength(0);

    // 3. В попапе нажать «לא עכשיו», затем в шите «לא עכשיו»
    await upsell.getByRole('button', { name: 'לא עכשיו' }).click();
    await expect(page.getByRole('button', { name: 'לשדרג ל-Premium' })).toBeHidden();

    await expect(page.getByText('פנוי/ה לדייט עכשיו?')).toBeVisible();
    await page.getByRole('button', { name: 'לא עכשיו' }).click();
    await expect(page.getByText('פנוי/ה לדייט עכשיו?')).toBeHidden();

    // Ожидаемо: кнопка «דייט עכשיו» без таймера, запроса set_date_now не было
    await expect(pill).toBeVisible();
    await expect(pill).toHaveText(/^\s*דייט עכשיו\s*$/);
    expect(setDateNowRequests).toHaveLength(0);
  });
});
